head.script:

	scwin.trigger1_onclick = function(e) {
		se.setRef("data:dataMap1.key1");
	};

	scwin.trigger2_onclick = function(e) {
		debugger;
		dataMap1.set( "key1", "change value11" );
		//alert(dataMap1.get("key1"));
//		se.commit();
	};


	scwin.trigger3_onclick = function(e) {
		se2.setRef( "data:dataMap2.key1" );
	};


	scwin.trigger4_onclick = function(e) {
		debugger;
		dataMap2.set( "key1", "change value22" );
		alert(dataMap2.get("key1"));
//		se2.commit();
	};

	scwin.trigger5_onclick = function(e) {
		se3.setRef("data:dataMap2.key1");
	};


	scwin.trigger7_onclick = function(e) {
		se3.setRef("data:dataMap1.key1");
	};

	scwin.trigger6_onclick = function(e) {
		dataMap2.set("key1" , "change key value" );
//		se3.commit();
		alert(dataMap2.get("key1"));
	};

	scwin.trigger8_onclick = function(e) {
		input1.setRef("data:dataMap1.key1");
	};

	scwin.trigger9_onclick = function(e) {
		dataMap1.set("key1" , "change input");
	};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('se___input').value == 'change value11';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
